function o(t){return t<1e3?`${t}ms`:t<6e4?`${(t/1e3).toFixed(1)}s`:`${Math.floor(t/6e4)}m ${Math.floor(t%6e4/1e3)}s`}function a(t,e){if(!t)return"—";const n=(e?new Date(e):new Date).getTime()-new Date(t).getTime();return n<0?"—":o(n)}function u(t){return a(t.started_at,t.ended_at)}function f(t){return t?new Date(t).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit",second:"2-digit"}):"—"}function c(t){if(!t)return"—";try{const e=new Date(t);return isNaN(e.getTime())?"—":e.toLocaleTimeString([],{hour:"2-digit",minute:"2-digit",second:"2-digit",fractionalSecondDigits:3})}catch{return"—"}}function d(t){if(!t)return"—";try{const e=new Date(t);return isNaN(e.getTime())?"—":e.toLocaleDateString([],{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"})}catch{return"—"}}function m(t){return t?new Date(t).toLocaleString([],{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"}):"—"}function g(t){return t<1024?`${t} B`:t<1024*1024?`${(t/1024).toFixed(1)} KB`:`${(t/(1024*1024)).toFixed(1)} MB`}function s(t){const e=t.filter(n=>n.started_at&&n.ended_at);if(e.length===0)return 0;const r=e.reduce((n,i)=>n+(new Date(i.ended_at).getTime()-new Date(i.started_at).getTime()),0);return Math.round(r/e.length)}export{f as a,u as b,s as c,a as d,m as e,o as f,c as g,g as h,d as i};
